<script setup>
import { ref } from 'vue'
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'

const props = defineProps(SHOPPING_OPERATION_PAGE_PROPS)
const emit = defineEmits(SHOPPING_OPERATION_PAGE_EVENTS)
const localize = (zh, en) => localizeOperationPage(props.languageBase, zh, en)
const pendingDeleteOrderId = ref('')
const isPantryItem = (product) =>
  product?.category === 'home' || /pantry|household|linen/.test(String(product?.id || ''))

const requestDelete = (orderId) => {
  if (pendingDeleteOrderId.value !== orderId) {
    pendingDeleteOrderId.value = orderId
    return
  }
  emit('delete-order', orderId)
  pendingDeleteOrderId.value = ''
}
</script>

<template>
  <main class="kurly-ops k-ops" :data-page="pageKey" data-testid="shopping-store-operation-page">
    <header class="ko-bar"><button type="button" :aria-label="localize('返回', 'Back')" @click="emit('back')"><i class="fas fa-arrow-left"></i></button><strong>Kurly</strong><div><button type="button" data-testid="shopping-open-service" :aria-label="localize('帮助', 'Help')" @click="emit('open-service')"><i class="fas fa-circle-question"></i></button><button type="button" :aria-label="localize('订单', 'Orders')" @click="emit('open-orders')"><i class="fas fa-receipt"></i></button><button type="button" :aria-label="localize('购物篮', 'Basket')" @click="emit('open-cart')"><i class="fas fa-basket-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>

    <section v-if="pageKey === 'cart'" id="shopping-cart" class="ko-basket">
      <header><small>TEMPERATURE BASKET</small><h1>{{ localize('确认商品，再进入配送核对', 'Review items before delivery checkout') }}</h1><p>{{ localize('生鲜与常温商品分组仅用于结算检查，不代表实际配送承诺。', 'Groups support checkout review and do not promise a delivery window.') }}</p></header>
      <div v-if="!cartItems.length" class="ko-empty"><i class="fas fa-basket-shopping"></i><strong>{{ localize('购物篮还是空的', 'Your basket is empty') }}</strong><p>{{ localize('返回首页继续选购。', 'Return to the shop to add items.') }}</p></div>
      <div v-else class="ko-basket-layout"><section><article v-for="line in cartItems" :key="line.productId"><span class="ko-item-media"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i></span><div class="ko-item-copy"><small>{{ isPantryItem(line.product) ? localize('常温与居家', 'PANTRY & HOME') : localize('保存方式待核对', 'STORAGE REVIEW') }}</small><strong>{{ productDisplayTitle(line.product) }}</strong><p>{{ formatOrderItemSubtotal({ ...line, quantity: 1, unitPriceCents: line.product.priceCents, currency: line.currency }) }} / {{ localize('件', 'item') }}</p><div><button type="button" :aria-label="localize('减少数量', 'Decrease quantity')" @click="emit('update-quantity', line.productId, -1)">−</button><span>{{ line.quantity }}</span><button type="button" :aria-label="localize('增加数量', 'Increase quantity')" @click="emit('update-quantity', line.productId, 1)">+</button></div></div><strong>{{ formatOrderItemSubtotal({ ...line, unitPriceCents: line.product.priceCents, currency: line.currency }) }}</strong></article></section><aside><small>ORDER SUMMARY</small><strong>{{ cartTotalLabel }}</strong><dl><div><dt>{{ localize('商品数量', 'Items') }}</dt><dd>{{ cartQuantity }}</dd></div><div><dt>{{ localize('配送时间与费用', 'Delivery & fee') }}</dt><dd>{{ localize('下一步确认', 'Review next') }}</dd></div></dl><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled', $event.target.checked)" />{{ localize('作为礼物配送', 'Send as a gift') }}</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId', $event.target.value)"><option value="">{{ localize('手动填写收件人', 'Enter recipient manually') }}</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" :placeholder="localize('收件人姓名', 'Recipient name')" @input="emit('update:giftRecipientName', $event.target.value)" /><button type="button" data-testid="shopping-checkout" @click="emit('checkout')">{{ localize('进入结算核对', 'Continue to checkout') }}</button></aside></div>
    </section>

    <section v-else-if="pageKey === 'orders'" id="shopping-orders" class="ko-orders">
      <header><div><small>MY KURLY</small><h1>{{ localize('订单记录', 'Orders') }}</h1></div><button type="button" @click="emit('open-logistics')">{{ localize('查看配送', 'Delivery status') }} <i class="fas fa-arrow-right"></i></button></header>
      <div v-if="!orders.length" class="ko-empty"><i class="fas fa-receipt"></i><strong>{{ localize('还没有订单', 'No orders yet') }}</strong></div>
      <article v-for="order in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><div class="ko-order-date"><i class="fas fa-basket-shopping"></i><small>{{ formatLogisticsDate(order.createdAt) }}</small></div><div><span>{{ orderStatusLabel(order.status) }}</span><h2>{{ order.items.map((item) => item.title).join(' / ') }}</h2><p>{{ order.itemCount }} {{ localize('件商品', 'items') }} · {{ formatOrderTotal(order) }}</p></div><button type="button" :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order', order.id)">{{ localize('查看订单', 'View') }}</button><div class="ko-delete"><button v-if="pendingDeleteOrderId !== order.id" type="button" :aria-label="localize('删除订单记录', 'Delete order record')" @click="requestDelete(order.id)"><i class="fas fa-trash"></i></button><template v-else><button type="button" @click="pendingDeleteOrderId = ''">{{ localize('取消', 'Cancel') }}</button><button type="button" @click="requestDelete(order.id)">{{ localize('确认删除', 'Delete') }}</button></template></div></article>
    </section>

    <section v-else-if="pageKey === 'logistics'" class="ko-logistics" data-testid="shopping-logistics-panel">
      <header><button type="button" @click="emit('open-orders')"><i class="fas fa-arrow-left"></i>{{ localize('订单', 'Orders') }}</button><small>DELIVERY STATUS</small><h1>{{ localize('只展示已记录的配送进度', 'Recorded delivery progress') }}</h1><p>{{ localize('没有订单事件时，不推测地点、时段或温度。', 'No location, timing, or temperature is inferred without an order event.') }}</p></header>
      <div v-if="!logisticsRows.length" class="ko-empty"><i class="fas fa-truck"></i><strong>{{ localize('暂无配送记录', 'No delivery records') }}</strong></div>
      <article v-for="row in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><div class="ko-progress"><span>{{ logisticsStatusLabel(row.status) }}</span><i></i><b>{{ row.latestEvent ? logisticsEventTypeLabel(row.latestEvent.type) : localize('等待记录', 'Awaiting event') }}</b></div><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary || row.summary }}</p><small v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ row.latestEvent.trackingCode || row.latestEvent.locationHint }}</small><button type="button" :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order', row.order.id)">{{ localize('查看订单详情', 'View order') }}</button><em :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</em></article>
    </section>

    <section v-else-if="selectedOrder" class="ko-detail" data-testid="shopping-order-detail-panel">
      <header><button type="button" data-testid="shopping-close-order-detail" @click="emit('close-order')"><i class="fas fa-arrow-left"></i></button><div><small>ORDER DETAIL</small><h1>{{ formatLogisticsDate(selectedOrder.createdAt) }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header>
      <section class="ko-detail-summary"><div><small>{{ localize('订单总额', 'Order total') }}</small><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong></div><p>{{ localize('配送时段以订单已保存信息和物流事件为准。', 'Delivery timing follows saved order facts and logistics events.') }}</p></section>
      <section class="ko-detail-items"><h2>{{ localize('商品', 'Items') }}</h2><article v-for="item in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><span>{{ item.productId?.includes('grocery') ? localize('生鲜', 'FRESH') : localize('已装袋', 'PACKED') }}</span><div><strong>{{ item.title }}</strong><p>{{ item.quantity }} × {{ formatOrderItemSubtotal({ ...item, quantity: 1 }) }}</p></div><b>{{ formatOrderItemSubtotal(item) }}</b></article></section>
      <section class="ko-timeline" data-testid="shopping-order-detail-timeline"><h2>{{ localize('配送记录', 'Delivery events') }}</h2><article v-for="event in selectedOrder.events || []" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><i class="fas fa-circle"></i><div><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary || event.title }}</p><span>{{ formatLogisticsDate(event.createdAt) }}</span></div></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">{{ localize('还没有已记录的配送事件。', 'No recorded delivery events yet.') }}</p></section>
      <footer><button type="button" data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order', selectedOrder.id)">{{ localize('确认完成', 'Complete') }}</button><button type="button" data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order', selectedOrder.id)">{{ localize('取消订单', 'Cancel order') }}</button><button v-if="pendingDeleteOrderId !== selectedOrder.id" type="button" data-testid="shopping-order-detail-delete" @click="requestDelete(selectedOrder.id)">{{ localize('删除记录', 'Delete record') }}</button><template v-else><button type="button" @click="pendingDeleteOrderId = ''">{{ localize('保留记录', 'Keep') }}</button><button type="button" data-testid="shopping-order-detail-delete-confirm" @click="requestDelete(selectedOrder.id)">{{ localize('确认删除', 'Confirm delete') }}</button></template></footer>
    </section>
  </main>
</template>

<style scoped>
.kurly-ops{--purple:#5f0080;--deep:#2f0a3b;--lime:#c7df5b;--ink:#211526;--muted:#756b79;--line:#e8e1ea;min-height:100%;color:var(--ink);background:#f8f6f8;font-family:"Noto Sans KR",Arial,sans-serif}.ko-bar{position:sticky;top:0;z-index:20;height:58px;padding:0 16px;display:grid;grid-template-columns:40px 1fr auto;align-items:center;border-bottom:1px solid var(--line);background:#fff}.ko-bar>strong{color:var(--purple);font:700 20px Georgia,serif}.ko-bar>div{display:flex}.ko-bar button{position:relative;width:40px;height:40px}.ko-bar b{position:absolute;top:1px;right:1px;min-width:16px;height:16px;display:grid;place-items:center;border-radius:9px;color:#fff;background:var(--purple);font-size:8px}.ko-basket>header,.ko-logistics>header{padding:38px 22px;color:#fff;background:var(--deep)}.ko-basket>header small,.ko-orders>header small,.ko-logistics>header small,.ko-detail>header small{color:var(--lime);font-size:8px;font-weight:900;letter-spacing:.13em}.ko-basket>header h1,.ko-logistics>header h1{max-width:650px;margin:9px 0 0;font:700 38px/1.08 Georgia,"Noto Serif KR",serif}.ko-basket>header p,.ko-logistics>header p{max-width:58ch;margin:12px 0 0;color:rgba(255,255,255,.68);font-size:9px;line-height:1.65}.ko-basket-layout{padding:18px 20px 60px;display:grid;grid-template-columns:1.25fr .75fr;gap:12px}.ko-basket-layout>section{display:grid;gap:8px}.ko-basket-layout article{padding:10px;display:grid;grid-template-columns:96px 1fr auto;gap:12px;align-items:center;border:1px solid var(--line);background:#fff}.ko-item-media{aspect-ratio:1;display:grid;place-items:center;overflow:hidden;border-radius:8px;background:#eee8f0;color:var(--purple);font-size:28px}.ko-item-media img{width:100%;height:100%;object-fit:cover}.ko-item-copy small{color:var(--purple);font-size:7px;font-weight:900}.ko-item-copy>strong{display:block;margin-top:5px;font-size:12px}.ko-item-copy p{margin:5px 0 0;color:var(--muted);font-size:8px}.ko-item-copy>div{width:104px;height:32px;margin-top:10px;display:grid;grid-template-columns:32px 1fr 32px;border:1px solid var(--line)}.ko-item-copy>div>*{display:grid;place-items:center;font-size:9px}.ko-basket-layout article>strong{font-size:10px}.ko-basket-layout>aside{align-self:start;padding:19px;border:1px solid var(--line);background:#fff}.ko-basket-layout aside>small{color:var(--purple);font-size:8px;font-weight:900}.ko-basket-layout aside>strong{display:block;margin-top:8px;font-size:23px}.ko-basket-layout dl{margin:18px 0;border-top:1px solid var(--line)}.ko-basket-layout dl div{padding:10px 0;display:flex;justify-content:space-between;border-bottom:1px solid var(--line);font-size:8px}.ko-basket-layout label{display:flex;align-items:center;gap:7px;font-size:9px}.ko-basket-layout select,.ko-basket-layout input:not([type=checkbox]){width:100%;height:38px;margin-top:8px;padding:0 9px;border:1px solid var(--line);font-size:9px}.ko-basket-layout aside>button{width:100%;height:48px;margin-top:15px;color:#fff;background:var(--purple);font-size:9px;font-weight:900}.ko-orders>header{padding:32px 20px;display:flex;align-items:end;justify-content:space-between;color:#fff;background:var(--deep)}.ko-orders h1{margin:8px 0 0;font:700 37px Georgia,serif}.ko-orders>header button{color:var(--lime);font-size:9px;font-weight:900}.ko-orders>article{margin:12px 18px;padding:14px;display:grid;grid-template-columns:74px 1fr auto auto;gap:13px;align-items:center;border:1px solid var(--line);background:#fff}.ko-order-date{aspect-ratio:1;display:grid;place-items:center;border-radius:50%;color:#fff;background:var(--purple)}.ko-order-date i{font-size:20px}.ko-order-date small{font-size:7px}.ko-orders article span{color:var(--purple);font-size:7px;font-weight:900}.ko-orders article h2{margin:6px 0 0;font-size:13px}.ko-orders article p{margin:6px 0 0;color:var(--muted);font-size:8px}.ko-orders article>button{font-size:8px;font-weight:900}.ko-delete{display:flex}.ko-delete button{min-width:32px;height:32px;padding:0 7px;color:var(--muted);font-size: