gin:5px 0 0;font-size:8px}.ko-timeline article{padding:10px 0;display:grid;grid-template-columns:22px 1fr;border-bottom:1px solid var(--line)}.ko-timeline article>i{color:var(--purple);font-size:7px}.ko-timeline strong,.ko-timeline p,.ko-timeline span{display:block;font-size:8px}.ko-timeline p,.ko-timeline span{color:var(--muted)}.ko-detail>footer{padding:8px 20px 60px;display:flex;gap:7px;flex-wrap:wrap}.ko-detail>footer button{min-width:110px;height:43px;padding:0 12px;border:1px solid var(--purple);color:var(--purple);font-size:8px;font-weight:900}.ko-detail>footer button:first-child{color:#fff;background:var(--purple)}.ko-detail>footer button:disabled{opacity:.3}.ko-empty{min-height:300px;display:grid;place-items:center;align-content:center;gap:9px;color:var(--muted)}.ko-empty i{color:var(--purple);font-size:27px}.ko-empty p{margin:0;font-size:8px}.kurly-ops button:focus-visible,.kurly-ops input:focus-visible,.kurly-ops select:focus-visible{outline:3px solid var(--lime);outline-offset:2px}@media(max-width:680px){.ko-basket-layout{grid-template-columns:1fr}.ko-orders>article{grid-template-columns:62px 1fr}.ko-orders article>button,.ko-delete{grid-column:2}.ko-detail-summary{align-items:flex-start;flex-direction:column}.ko-detail>footer{display:grid;grid-template-columns:1fr 1fr}.ko-detail>footer button{min-width:0}}
